INSERT INTO query_window (key, cursor, has_next, total, pages, issued, applied, generation, landed_at) VALUES (?1, ?2, ?3, ?8, ?9, ?4, ?5, ?6, ?7) ON CONFLICT (key) DO UPDATE SET cursor = excluded.cursor, has_next = excluded.has_next, total = excluded.total, pages = excluded.pages, issued = excluded.issued, applied = excluded.applied, generation = excluded.generation